WITH flattened AS (SELECT id, host, level, status_code, k, v FROM app_logs LATERAL VIEW OUTER EXPLODE(context) t AS k, v), unpacked AS (SELECT id, k, SHIFTRIGHT(status_code, 2) AS status_code_high, CAST((status_code & 4) != 0 AS INT) AS flag_bit4 FROM flattened WHERE k IS NULL), enriched AS (SELECT *, SUM(status_code_high) OVER (PARTITION BY k) AS k_sum_status_code_high, PERCENT_RANK() OVER (ORDER BY flag_bit4 DESC NULLS LAST) AS flag_bit4_percent_rank, RANK() OVER (ORDER BY status_code_high DESC NULLS LAST) AS status_code_high_rank, DENSE_RANK() OVER (ORDER BY status_code_high) AS status_code_high_dense_rank, RANK() OVER (PARTITION BY k ORDER BY flag_bit4 DESC NULLS FIRST) AS flag_bit4_rank FROM unpacked), base AS (SELECT *, ROUND(flag_bit4 * 0.85, 2) AS flag_bit4_scaled, LOWER(k) AS k_lower FROM enriched WHERE k IS NOT NULL), enriched_app_logs AS (SELECT *, RANK() OVER (PARTITION BY k ORDER BY flag_bit4_scaled DESC) AS flag_bit4_scaled_rank, DENSE_RANK() OVER (PARTITION BY k ORDER BY status_code_high NULLS FIRST) AS status_code_high_dense_rank_2, SUM(flag_bit4) OVER (PARTITION BY k) AS k_sum_flag_bit4, MAX(status_code_high) OVER (PARTITION BY k) AS k_max_status_code_high FROM base), filtered AS (SELECT *, flag_bit4_percent_rank / NULLIF(flag_bit4_scaled, 0) AS flag_bit4_percent_rank_per_flag_bit4_scaled, COALESCE(k, 'UNKNOWN') AS k_filled FROM enriched_app_logs WHERE k IS NOT NULL), daily AS (SELECT k, MAX(flag_bit4_rank) AS max_flag_bit4_rank, COUNT(CASE WHEN k = 'region' THEN 1 END) AS region_count, PERCENTILE_APPROX(k_max_status_code_high, ARRAY(0.25, 0.5, 0.75)) AS k_max_status_code_high_quartiles FROM filtered GROUP BY 1) SELECT k, max_flag_bit4_rank, region_count FROM daily ORDER BY max_flag_bit4_rank DESC NULLS FIRST, k DESC
